-- Consolidated DuckDB startup schema, including final notebook annotation column.
-- Empty-database view profile; runtime refreshes external Parquet views.
-- Reconstructed in memory; no production data was accessed.

CREATE TABLE bronze_clickstream(event_id VARCHAR PRIMARY KEY, session_id VARCHAR NOT NULL, user_id BIGINT NOT NULL, event_type VARCHAR NOT NULL, page_path VARCHAR NOT NULL, target_element VARCHAR, dwell_time_ms BIGINT DEFAULT(0), created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_course_interactions(interaction_id VARCHAR PRIMARY KEY, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, action_type VARCHAR NOT NULL, rating_score DOUBLE, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_interactions(interaction_id BIGINT PRIMARY KEY, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, lesson_id BIGINT, node_id BIGINT, action_type VARCHAR NOT NULL, score DOUBLE, status VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_learning_events(event_id VARCHAR PRIMARY KEY, event_type VARCHAR NOT NULL, student_id BIGINT NOT NULL, session_id VARCHAR, course_id BIGINT, lesson_id BIGINT, question_id BIGINT, skill_id BIGINT, difficulty DOUBLE, correct BOOLEAN, attempt_no INTEGER, response_time_ms BIGINT, hint_count INTEGER, metadata_json VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_login_logs(login_id VARCHAR PRIMARY KEY, user_id BIGINT NOT NULL, login_type VARCHAR NOT NULL, login_method VARCHAR, ip_address VARCHAR, user_agent VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_recommendation_events(event_id VARCHAR PRIMARY KEY, event_time TIMESTAMP NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT, surface VARCHAR NOT NULL, event_type VARCHAR NOT NULL, recommendation_id VARCHAR NOT NULL, recommendation_set_id VARCHAR, entity_type VARCHAR, entity_id VARCHAR, rank INTEGER, metadata_json VARCHAR, ingested_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE bronze_user_onboarding(user_id BIGINT PRIMARY KEY, interested_categories VARCHAR, target_career VARCHAR, experience_level VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE TABLE gold_learner_skill_states(student_id BIGINT, skill_id BIGINT, mastery_score DOUBLE DEFAULT(0.0), confidence_score DOUBLE DEFAULT(0.0), attempt_count INTEGER DEFAULT(0), accuracy DOUBLE DEFAULT(0.0), avg_response_time_ms BIGINT, hint_dependency DOUBLE DEFAULT(0.0), recommended_difficulty DOUBLE, last_practiced_at TIMESTAMP, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), PRIMARY KEY(student_id, skill_id));

CREATE TABLE learner_profile_snapshots(user_id BIGINT, course_id BIGINT, profile_json VARCHAR NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), PRIMARY KEY(user_id, course_id));

CREATE TABLE notebook_entries(id VARCHAR PRIMARY KEY, user_id BIGINT NOT NULL, course_id BIGINT, node_id BIGINT, title VARCHAR NOT NULL, "content" VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP), annotation VARCHAR);

CREATE TABLE sent_notifications(user_id BIGINT NOT NULL, alert_type VARCHAR NOT NULL, node_id BIGINT, sent_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP));

CREATE INDEX idx_bronze_clickstream_user ON bronze_clickstream(user_id);

CREATE INDEX idx_bronze_course_interactions_lookup ON bronze_course_interactions(user_id, course_id);

CREATE INDEX idx_bronze_interactions_lookup ON bronze_interactions(user_id, course_id);

CREATE INDEX idx_bronze_learning_events_skill ON bronze_learning_events(skill_id, student_id);

CREATE INDEX idx_bronze_learning_events_student ON bronze_learning_events(student_id, created_at);

CREATE INDEX idx_bronze_login_logs_user ON bronze_login_logs(user_id);

CREATE INDEX idx_bronze_recommendation_events_lookup ON bronze_recommendation_events(user_id, recommendation_id);

CREATE INDEX idx_gold_learner_skill_states_mastery ON gold_learner_skill_states(mastery_score);

CREATE INDEX idx_sent_notifications_lookup ON sent_notifications(user_id, alert_type, node_id);

CREATE VIEW unified_interactions AS SELECT interaction_id, user_id, course_id, lesson_id, node_id, action_type, score, status, created_at FROM bronze_interactions;

CREATE VIEW gold_student_course_metrics AS WITH base_metrics AS (SELECT user_id, course_id, count(DISTINCT COALESCE(lesson_id, node_id)) FILTER (WHERE (action_type IN ('lesson_complete', 'lesson_completed'))) AS completed_lessons_count, count(DISTINCT COALESCE(lesson_id, node_id)) FILTER (WHERE (action_type IN ('lesson_view', 'lesson_viewed'))) AS viewed_lessons_count, count_star() FILTER (WHERE (action_type = 'quick_check_correct')) AS correct_checks_count, count_star() FILTER (WHERE (action_type = 'quick_check_incorrect')) AS incorrect_checks_count, count_star() FILTER (WHERE (action_type = 'ask_ai')) AS ask_ai_count, count_star() FILTER (WHERE (action_type = 'flashcard_flip')) AS flashcard_flips_count, count_star() AS total_interactions_count, max(created_at) AS last_active_at FROM unified_interactions GROUP BY user_id, course_id)SELECT *, round(CASE  WHEN (((correct_checks_count + incorrect_checks_count) > 0)) THEN (((correct_checks_count * 1.0) / (correct_checks_count + incorrect_checks_count))) ELSE 0.0 END, 2) AS check_accuracy, CASE  WHEN ((flashcard_flips_count >= greatest(ask_ai_count, (correct_checks_count + incorrect_checks_count), 1))) THEN ('Chủ động (Flashcard)') WHEN ((ask_ai_count >= greatest(flashcard_flips_count, (correct_checks_count + incorrect_checks_count), 1))) THEN ('Tương tác AI') WHEN (((correct_checks_count + incorrect_checks_count) >= greatest(flashcard_flips_count, ask_ai_count, 1))) THEN ('Thực hành (Trắc nghiệm)') ELSE 'Đọc hiểu & Lý thuyết' END AS learning_style, CASE  WHEN ((total_interactions_count >= 15)) THEN ('Rất tích cực') WHEN ((total_interactions_count >= 5)) THEN ('Tích cực') ELSE 'Cần cố gắng' END AS engagement_level, CASE  WHEN (((correct_checks_count + incorrect_checks_count) = 0)) THEN ('Nên làm thêm Quick Check để tự đánh giá.') WHEN ((((correct_checks_count * 1.0) / (correct_checks_count + incorrect_checks_count)) < 0.6)) THEN ('Độ chính xác thấp, nên xem kỹ lại lý thuyết và thảo luận với AI.') WHEN ((flashcard_flips_count < 3)) THEN ('Nên dùng Flashcards để ghi nhớ nhanh các khái niệm chính.') WHEN ((ask_ai_count = 0)) THEN ('Đừng ngần ngại sử dụng Hỏi AI khi gặp kiến thức khó.') ELSE 'Đang học tập rất tốt! Hãy tiếp tục duy trì phong độ.' END AS study_recommendation FROM base_metrics;

CREATE VIEW gold_concept_struggles AS SELECT user_id, course_id, node_id, count_star() FILTER (WHERE (action_type = 'quick_check_incorrect')) AS incorrect_checks_count, count_star() FILTER (WHERE (action_type = 'quick_check_correct')) AS correct_checks_count, round(CASE  WHEN (((count_star() FILTER (WHERE (action_type = 'quick_check_correct')) + count_star() FILTER (WHERE (action_type = 'quick_check_incorrect'))) > 0)) THEN (((count_star() FILTER (WHERE (action_type = 'quick_check_incorrect')) * 1.0) / (count_star() FILTER (WHERE (action_type = 'quick_check_correct')) + count_star() FILTER (WHERE (action_type = 'quick_check_incorrect'))))) ELSE 0.0 END, 2) AS struggle_rate, max(created_at) AS last_attempt_at FROM unified_interactions WHERE (node_id IS NOT NULL) GROUP BY user_id, course_id, node_id HAVING ((count_star() FILTER (WHERE (action_type = 'quick_check_incorrect')) >= 1) AND (count_star() FILTER (WHERE (action_type = 'quick_check_incorrect')) > count_star() FILTER (WHERE (action_type = 'quick_check_correct'))));

CREATE VIEW gold_user_item_matrix AS SELECT user_id, course_id, node_id, count_star() AS total_interactions, sum(CASE  WHEN ((action_type IN ('lesson_view', 'lesson_viewed'))) THEN (1.0) WHEN ((action_type IN ('lesson_complete', 'lesson_completed'))) THEN (2.0) WHEN ((action_type = 'flashcard_flip')) THEN (1.0) WHEN ((action_type = 'quick_check_correct')) THEN (2.0) WHEN ((action_type = 'quick_check_incorrect')) THEN (0.5) WHEN ((action_type = 'ask_ai')) THEN (1.5) WHEN ((action_type = 'preference_elicited')) THEN (3.0) ELSE 0.5 END) AS implicit_affinity_score, max(created_at) AS last_interaction_at FROM unified_interactions WHERE (node_id IS NOT NULL) GROUP BY user_id, course_id, node_id;

CREATE VIEW gold_struggle_alerts AS (((((SELECT user_id, course_id, node_id, 'concept_struggle' AS alert_type, (((('Học viên đang gặp khó khăn ở khái niệm (Khái niệm ID: ' || CAST(node_id AS VARCHAR)) || ') với tỷ lệ làm sai là ') || CAST(round((struggle_rate * 100), 0) AS VARCHAR)) || '%. Hãy ôn tập lại bài học!') AS alert_message, last_attempt_at AS detected_at FROM gold_concept_struggles WHERE (incorrect_checks_count >= 1)) UNION ALL (SELECT user_id, course_id, NULL AS node_id, 'low_performance' AS alert_type, (('Cảnh báo: Bạn đang có độ chính xác Quick Check khá thấp (' || CAST(round((check_accuracy * 100), 0) AS VARCHAR)) || '%). Hãy dành thời gian xem kỹ lại lý thuyết.') AS alert_message, last_active_at AS detected_at FROM gold_student_course_metrics WHERE (((correct_checks_count + incorrect_checks_count) >= 3) AND (check_accuracy < 0.60)))) UNION ALL (SELECT user_id, course_id, NULL AS node_id, 'inactivity' AS alert_type, 'Đã lâu bạn chưa tham gia học tập. Hãy quay lại tiếp tục lộ trình khi sẵn sàng.' AS alert_message, last_active_at AS detected_at FROM gold_student_course_metrics WHERE (last_active_at < (now() - to_days(CAST(trunc(CAST(7 AS DOUBLE)) AS INTEGER)))))) UNION ALL (SELECT user_id, course_id, NULL AS node_id, 'positive_reinforcement' AS alert_type, (('Tuyệt vời! Bạn đang học tập rất tích cực với ' || CAST(completed_lessons_count AS VARCHAR)) || ' bài học đã hoàn thành. Hãy tiếp tục phát huy nhé!') AS alert_message, last_active_at AS detected_at FROM gold_student_course_metrics WHERE ((completed_lessons_count >= 3) AND (engagement_level = 'Rất tích cực')))) UNION ALL (SELECT user_id, course_id, NULL AS node_id, 'ai_suggestion' AS alert_type, 'Gợi ý: Bạn đang gặp một số câu hỏi khó ở chủ đề này. Hãy thử nhấn nút "Hỏi AI" ở góc phải để được giải thích chi tiết!' AS alert_message, last_active_at AS detected_at FROM gold_student_course_metrics WHERE ((ask_ai_count = 0) AND ((correct_checks_count + incorrect_checks_count) > 0) AND (check_accuracy < 0.8)))) UNION ALL (SELECT user_id, course_id, NULL AS node_id, 'flashcard_suggestion' AS alert_type, 'Gợi ý: Bạn có thể sử dụng Thẻ ghi nhớ (Flashcards) để ôn tập nhanh các từ khóa quan trọng của bài học!' AS alert_message, last_active_at AS detected_at FROM gold_student_course_metrics WHERE ((flashcard_flips_count = 0) AND (viewed_lessons_count >= 2)));

CREATE VIEW gold_study_recommendations AS WITH user_courses AS (SELECT DISTINCT user_id, course_id FROM unified_interactions), popular_concepts AS (SELECT course_id, node_id AS popular_node_id, count_star() AS interaction_count, row_number() OVER (PARTITION BY course_id ORDER BY count_star() DESC) AS pop_rank FROM unified_interactions WHERE ((node_id IS NOT NULL) AND (action_type IN ('lesson_view', 'lesson_viewed', 'lesson_complete', 'lesson_completed'))) GROUP BY course_id, node_id), weakest_concepts AS (SELECT user_id, course_id, node_id AS weakest_node_id, struggle_rate, row_number() OVER (PARTITION BY user_id, course_id ORDER BY struggle_rate DESC) AS rank FROM gold_concept_struggles), student_metrics AS (SELECT user_id, course_id, check_accuracy, viewed_lessons_count FROM gold_student_course_metrics)SELECT uc.user_id, uc.course_id, CASE  WHEN ((w.weakest_node_id IS NOT NULL)) THEN ('review_struggle_concept') WHEN (((sm.check_accuracy < 0.60) AND (sm.viewed_lessons_count > 0))) THEN ('discuss_with_ai') WHEN (((sm.viewed_lessons_count IS NULL) OR (sm.viewed_lessons_count = 0))) THEN ('learn_popular_lesson') ELSE 'learn_next_lesson' END AS recommended_action_type, CASE  WHEN ((w.weakest_node_id IS NOT NULL)) THEN (w.weakest_node_id) WHEN (((sm.viewed_lessons_count IS NULL) OR (sm.viewed_lessons_count = 0))) THEN (pc.popular_node_id) ELSE NULL END AS recommended_node_id, CASE  WHEN ((w.weakest_node_id IS NOT NULL)) THEN ((('Bạn đang gặp khó khăn ở khái niệm (ID: ' || CAST(w.weakest_node_id AS VARCHAR)) || '). Hãy ôn tập lại lý thuyết bài học này!')) WHEN (((sm.check_accuracy < 0.60) AND (sm.viewed_lessons_count > 0))) THEN ('Cảnh báo: Độ chính xác Quick Check của bạn đang dưới 60%. Hãy thảo luận với AI Mentor để củng cố kiến thức.') WHEN (((sm.viewed_lessons_count IS NULL) OR (sm.viewed_lessons_count = 0))) THEN ((('Khóa học mới! Hãy bắt đầu với chủ đề phổ biến nhất: (ID: ' || CAST(COALESCE(pc.popular_node_id, 0) AS VARCHAR)) || ').')) ELSE 'Tiến độ học tập rất tốt! Hãy tiếp tục học bài học tiếp theo trong giáo trình.' END AS recommendation_message, CURRENT_TIMESTAMP AS generated_at FROM user_courses AS uc LEFT JOIN weakest_concepts AS w ON (((uc.user_id = w.user_id) AND (uc.course_id = w.course_id) AND (w.rank = 1))) LEFT JOIN student_metrics AS sm ON (((uc.user_id = sm.user_id) AND (uc.course_id = sm.course_id))) LEFT JOIN popular_concepts AS pc ON (((uc.course_id = pc.course_id) AND (pc.pop_rank = 1)));

CREATE VIEW gold_daily_user_logins AS SELECT user_id, CAST(created_at AS DATE) AS login_date, count_star() AS total_logins_count, count(DISTINCT main.date_part('hour', created_at)) AS active_hours_count, min(created_at) AS first_login_at, max(created_at) AS last_login_at, CASE  WHEN ((count_star() >= 5)) THEN ('Rất thường xuyên') WHEN ((count_star() >= 2)) THEN ('Chăm chỉ') ELSE 'Đăng nhập 1 lần/ngày' END AS visit_frequency_level FROM bronze_login_logs GROUP BY user_id, CAST(created_at AS DATE);

CREATE VIEW gold_course_discovery_recommendations AS WITH course_stats AS (SELECT course_id, count(DISTINCT user_id) FILTER (WHERE (action_type = 'enroll')) AS enrolled_students_count, count_star() FILTER (WHERE (action_type = 'view')) AS total_views_count, count_star() FILTER (WHERE (action_type = 'bookmark')) AS total_bookmarks_count, round(avg(rating_score), 2) AS avg_rating FROM bronze_course_interactions GROUP BY course_id)SELECT cs.course_id, COALESCE(cs.enrolled_students_count, 0) AS enrolled_students_count, COALESCE(cs.total_views_count, 0) AS total_views_count, COALESCE(cs.total_bookmarks_count, 0) AS total_bookmarks_count, COALESCE(cs.avg_rating, 0.0) AS avg_rating, CASE  WHEN ((cs.enrolled_students_count >= 10)) THEN ('Phổ biến nhất (Trending)') WHEN ((cs.avg_rating >= 4.5)) THEN ('Đánh giá cao nhất (Top Rated)') ELSE 'Gợi ý cho học viên mới (Cold Start Candidate)' END AS recommendation_tag, CURRENT_TIMESTAMP AS calculated_at FROM course_stats AS cs;

CREATE VIEW gold_user_profile_vectors AS WITH user_logins_summary AS (SELECT user_id, count_star() AS total_logins, count(DISTINCT main.date_part('hour', created_at)) AS active_hours FROM bronze_login_logs GROUP BY user_id), user_clickstream_summary AS (SELECT user_id, (sum(dwell_time_ms) / 1000.0) AS total_dwell_seconds, count_star() AS total_clicks FROM bronze_clickstream GROUP BY user_id), user_notebook_summary AS (SELECT user_id, count_star() AS notes_count FROM notebook_entries GROUP BY user_id), user_base AS (SELECT m.user_id, 'UNSPECIFIED' AS team, 'STUDENT' AS "role", COALESCE(o.target_career, 'UNSPECIFIED') AS target_career, COALESCE(m.check_accuracy, 0.0) AS check_accuracy, COALESCE(m.completed_lessons_count, 0) AS completed_lessons_count, COALESCE(m.ask_ai_count, 0) AS ask_ai_count, COALESCE(l.total_logins, 0) AS total_logins, COALESCE(c.total_dwell_seconds, 0) AS total_dwell_seconds, COALESCE(n.notes_count, 0) AS notes_count FROM gold_student_course_metrics AS m LEFT JOIN bronze_user_onboarding AS o ON ((m.user_id = o.user_id)) LEFT JOIN user_logins_summary AS l ON ((m.user_id = l.user_id)) LEFT JOIN user_clickstream_summary AS c ON ((m.user_id = c.user_id)) LEFT JOIN user_notebook_summary AS n ON ((m.user_id = n.user_id)))SELECT user_id, team, "role", target_career, check_accuracy, completed_lessons_count, total_logins, total_dwell_seconds, ask_ai_count, notes_count, main.list_value(CASE  WHEN ((team = 'ENGINEER')) THEN (1.0) ELSE 0.0 END, CASE  WHEN ((team = 'RESEARCH')) THEN (1.0) ELSE 0.0 END, CASE  WHEN ((team = 'MEDIA')) THEN (1.0) ELSE 0.0 END, CASE  WHEN ((team = 'EVENT')) THEN (1.0) ELSE 0.0 END, round(least(check_accuracy, 1.0), 2), round(least((completed_lessons_count / 10.0), 1.0), 2), round(least((total_logins / 10.0), 1.0), 2), round(least((total_dwell_seconds / 3600.0), 1.0), 2), round(least((ask_ai_count / 10.0), 1.0), 2), round(least((notes_count / 5.0), 1.0), 2)) AS user_vector, CURRENT_TIMESTAMP AS updated_at FROM user_base;

CREATE VIEW gold_item_profile_vectors AS WITH item_stats AS (SELECT course_id, count(DISTINCT user_id) FILTER (WHERE (action_type = 'enroll')) AS enrolled_count, count_star() FILTER (WHERE (action_type = 'view')) AS view_count, count_star() FILTER (WHERE (action_type = 'bookmark')) AS bookmark_count, COALESCE(round(avg(rating_score), 2), 0.0) AS avg_rating FROM bronze_course_interactions GROUP BY course_id)SELECT course_id, COALESCE(enrolled_count, 0) AS enrolled_count, COALESCE(view_count, 0) AS view_count, COALESCE(bookmark_count, 0) AS bookmark_count, COALESCE(avg_rating, 0.0) AS avg_rating, main.list_value(round(least((COALESCE(enrolled_count, 0) / 100.0), 1.0), 2), round(least((COALESCE(view_count, 0) / 500.0), 1.0), 2), round(least((COALESCE(bookmark_count, 0) / 50.0), 1.0), 2), round(least((COALESCE(avg_rating, 0.0) / 5.0), 1.0), 2)) AS item_vector, CURRENT_TIMESTAMP AS updated_at FROM item_stats;

CREATE VIEW gold_vector_recommender_scores AS WITH user_item_cross AS (SELECT u.user_id, u.team, i.course_id, u.user_vector, i.item_vector, round(least(((((u.user_vector[5] * i.item_vector[4]) + (u.user_vector[6] * i.item_vector[1])) + (u.user_vector[7] * i.item_vector[2])) + 0.2), 1.0), 2) AS similarity_match_score FROM gold_user_profile_vectors AS u , gold_item_profile_vectors AS i)SELECT user_id, course_id, team, similarity_match_score, round((similarity_match_score * 100), 0) AS match_percentage, CASE  WHEN ((similarity_match_score >= 0.8)) THEN (('🎯 Khớp tuyệt đối với Profile & Team ' || team)) WHEN ((similarity_match_score >= 0.6)) THEN ('👍 Phù hợp với định hướng học tập') ELSE '⭐ Gợi ý bổ trợ kiến thức' END AS recommendation_reason, CURRENT_TIMESTAMP AS calculated_at FROM user_item_cross ORDER BY user_id, similarity_match_score DESC;
